#include <bits/stdc++.h>
using namespace std;


void solve(){
    int n;
    cin >> n;
    vector <int> a(n);
    for (int i = 0;i < n;i++) cin >> a[i];
    
    if (n == 2){
        cout << abs(a[1] - a[0]) << "\n";
        return;
    }
    

    int mx = 0;
    int smx = 0;
    
    for (int i = 1;i< n;i++){
        int curr = abs(a[i] - a[i-1]);
        if (curr > mx){
            smx = mx;
            mx = curr;
        }
        else if (curr > smx){
            smx = curr;
        }
        
    }
    
    int curr_l = abs(a[0] - a[a.size()-1]);
    if (curr_l >= mx){
        cout << mx << "\n";
    }else{
        cout << max(smx,curr_l) << "\n";
    }
    // cout << mx << "\n";
    // cout << smx << "tt\n";
    
}

int main() {
	int test;
	cin >> test;
	while(test--){
	    solve();
	}

}
